INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'A shirt requires 1.4 meters of fabric per piece. For an order of 5,000 shirts, how many total meters of fabric are needed (ignoring cutting waste)?', '["7,000 meters","5,000 meters","1.4 meters","3,571 meters"]'::jsonb, '7,000 meters', 'Total fabric = fabric per piece × number of pieces = 1.4 × 5,000 = 7,000 meters.', 1, '{"fabric-consumption-calc"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'intermediate', 'multiple_choice', 'A shirt requires 1.4 meters of fabric per piece, plus 8% cutting waste allowance. For an order of 5,000 shirts, approximately how many total meters of fabric must be purchased?', '["≈ 7,560 meters","7,000 meters","≈ 6,440 meters","≈ 5,400 meters"]'::jsonb, '≈ 7,560 meters', 'Total fabric with waste = (fabric per piece × pieces) × (1 + waste%) = 7,000 × 1.08 = 7,560 meters.', 2, '{"fabric-consumption-with-waste"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'A loom achieves 320 actual picks per minute against a theoretical maximum of 400 picks per minute. What is the loom''s efficiency percentage?', '["80%","125%","40%","320%"]'::jsonb, '80%', 'Efficiency % = (actual / theoretical) × 100 = (320 / 400) × 100 = 80%.', 1, '{"loom-efficiency-calc"}'::text[]),
('4b495e60-fc2b-4165-a0c7-e0b144e931f7', 'basic', 'multiple_choice', 'A loom achieves 340 actual picks per minute against a theoretical maximum of 400 picks per minute. What is the loom''s efficiency percentage?', '["85%","118%","40%","340%"]'::jsonb, '85%', 'Efficiency % = (actual / theoretical) × 100 = (340 / 400) × 100 = 85%.', 1, '{"loom-efficiency-calc"}'::text[]);
